"""The Google account linked to a user (generated by Shikshya, P1b.6 R2): its subject id, never its email."""
from django.conf import settings
from django.db import models


class GoogleIdentity(models.Model):
    user = models.OneToOneField(settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name="google_identity")
    sub = models.CharField(max_length=255, unique=True)
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return "google:%s" % self.user_id
